# -*- coding: utf-8 -*-
# BTC / ETH 双均线趋势策略（4h）
# 信号：快线 > 慢线 视为趋势向上 -> 该标的持有目标仓位；否则清仓
# 风控：单标的成本止损 + 组合回撤熔断 + 总仓位上限
# 数据：只用已收盘 bar（ctx.indicators 返回当前已收盘值），下单在下一根 bar 开盘撮合

PARAMS = {
    "fast": 20,             # 快线周期（根 4h K）
    "slow": 60,             # 慢线周期（根 4h K）
    "target_pct": 0.45,     # 单标的趋势向上时的目标仓位（占总权益）
    "max_gross": 0.90,      # 组合总仓位上限（留出不小于 10% 现金）
    "stop_loss": 0.08,      # 单标的相对持仓成本的止损比例（0 = 关闭）
    "dd_stop": 0.20,        # 组合权益自峰值回撤的熔断阈值（0 = 关闭）
    "dd_pause_bars": 10,    # 熔断后禁止开仓的 bar 数（4h * 10 = 约 40 小时）
    "min_trade_pct": 0.02,  # 目标仓位与当前仓位偏差超过该值才调仓，减少无谓换手
}


def initialize(ctx):
    set_benchmark(ctx.securities[0])
    g.peak_value = 0.0        # 组合权益历史峰值
    g.pause_left = 0          # 熔断剩余暂停 bar 数
    g.stopped = {}            # 被止损封锁的标的：{security: True}
    log.info("双均线趋势策略启动 fast=%d slow=%d 单标的目标仓位=%.0f%% 总仓位上限=%.0f%%"
             % (PARAMS["fast"], PARAMS["slow"],
                PARAMS["target_pct"] * 100, PARAMS["max_gross"] * 100))


def _valid(x):
    """指标预热期会返回 None / nan，这类值一律视为无效。"""
    return x is not None and x == x


def _amount(ctx, sec):
    """当前持仓数量（无持仓返回 0）。"""
    pos = ctx.position(sec)
    if pos is None:
        return 0.0
    return pos.amount or 0.0


def _weight(ctx, sec, total):
    """当前持仓市值占总权益的比例。"""
    if total <= 0:
        return 0.0
    pos = ctx.position(sec)
    if pos is None:
        return 0.0
    return (pos.value or 0.0) / total


def handle_data(ctx):
    total = ctx.portfolio.total_value
    if total is None or total <= 0:
        return

    # 更新权益峰值
    if total > g.peak_value:
        g.peak_value = total

    # ---------- 组合级回撤熔断：清仓并暂停开仓 ----------
    if PARAMS["dd_stop"] > 0 and g.peak_value > 0:
        dd = 1.0 - total / g.peak_value
        if dd >= PARAMS["dd_stop"] and g.pause_left <= 0:
            for sec in ctx.securities:
                if _amount(ctx, sec) > 0:
                    order_target_percent(sec, 0.0)
            g.pause_left = int(PARAMS["dd_pause_bars"])
            g.peak_value = total  # 重置峰值，避免同一回撤反复触发
            log.info("组合回撤 %.2f%% 触发熔断：清仓并暂停 %d 根 bar"
                     % (dd * 100, g.pause_left))
            record(drawdown=dd, gross=0.0)
            return

    paused = g.pause_left > 0
    if paused:
        g.pause_left -= 1

    cd = get_current_data() or {}

    # ---------- 逐标的计算目标仓位 ----------
    desired = {}
    for sec in ctx.securities:
        fast_ma = ctx.indicators.sma(sec, int(PARAMS["fast"]))
        slow_ma = ctx.indicators.sma(sec, int(PARAMS["slow"]))
        if not _valid(fast_ma) or not _valid(slow_ma):
            continue  # 预热不足，维持现状不动

        amt = _amount(ctx, sec)
        pos = ctx.position(sec)
        bar = cd.get(sec) or {}
        last = bar.get("last_price")

        up = fast_ma > slow_ma
        if not up:
            g.stopped[sec] = False  # 死叉后解除该标的的止损封锁

        # ---------- 单标的成本止损 ----------
        if amt > 0 and PARAMS["stop_loss"] > 0 and pos is not None:
            avg = pos.avg_cost or 0.0
            if avg > 0 and last is not None and last > 0:
                if (last - avg) / avg <= -PARAMS["stop_loss"]:
                    g.stopped[sec] = True
                    desired[sec] = 0.0
                    log.info("%s 触发止损：持仓成本 %.4f / 现价 %.4f，清仓并等待死叉后重入"
                             % (sec, avg, last))
                    continue

        # ---------- 趋势信号 + 空仓条件 ----------
        if paused or g.stopped.get(sec, False) or not up:
            desired[sec] = 0.0
        else:
            desired[sec] = PARAMS["target_pct"]

    if not desired:
        return

    # ---------- 总仓位上限缩放 ----------
    gross_target = 0.0
    for v in desired.values():
        gross_target += v
    scale = 1.0
    if gross_target > PARAMS["max_gross"] and gross_target > 0:
        scale = PARAMS["max_gross"] / gross_target

    # 收集需要调整的标的，按「目标 - 当前」升序：先减仓、后加仓，避免瞬时现金不足
    orders = []
    for sec, tgt in desired.items():
        w = tgt * scale
        cur = _weight(ctx, sec, total)
        if abs(w - cur) >= PARAMS["min_trade_pct"]:
            orders.append((w - cur, w, sec))
    orders.sort(key=lambda x: x[0])

    for _, w, sec in orders:
        bar = cd.get(sec) or {}
        if bar.get("is_tradable", True) is False:
            continue
        order_target_percent(sec, w)

    # ---------- 记录组合状态 ----------
    gross_now = 0.0
    for sec in ctx.securities:
        gross_now += _weight(ctx, sec, total)
    dd_now = 0.0
    if g.peak_value > 0:
        dd_now = 1.0 - total / g.peak_value
    record(gross=gross_now, drawdown=dd_now)

